        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "Si je vaux quelque chose aujourd'hui, c'est que je suis seul et que je hais.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "Je n'ai guère de souci de beauté ni de perfection. Je me moque des grands siècles. Je n'ai souci que de vie, de lutte, de fièvre. Je suis à l'aise parmi notre génération.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "J'aime les ragoûts littéraires fortement épicés, les œuvres de dédacence où une sorte de sensibilité maladive remplace la santé plantureuse des époques classiques. Je suis de mon âge.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "La science du beau est une drôlerie inventée par les philosophes pour la plus grande hilarité des artistes.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "Une œuvre d'art est un coin de la création vu à travers un tempérament.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "La mort n'était bonne que parce qu'elle supprimait l'être d'un coup, pour toujours. Oh ! dormir comme les pierres, rentrer dans l'argile, n'être plus !", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "La science a-t-elle promis le bonheur ? Je ne le crois pas. Elle a promis la vérité, et la question est de savoir si l’on fera jamais du bonheur avec de la vérité.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "Paris flambait, ensemencé de lumière par le divin soleil, roulant dans sa gloire la moisson future de vérité et de justice.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "L’idée supérieure de discipline, qui est dans le sang de ces soldats, ne suffit-elle à infirmer leur pouvoir d’équité ? Qui dit discipline dit obéissance.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "La vérité est en marche et rien ne l’arrêtera.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "Quand on enferme la vérité sous terre, elle s’y amasse, elle y prend une force telle d’explosion, que, le jour où elle éclate, elle fait tout sauter avec elle. On verra bien si l’on ne vient pas de préparer, pour plus tard, le plus retentissant des désastres.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "La vérité et la justice sont souveraines, car elles seules assurent la grandeur des nations.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "Les sanglots d'un homme ont des sécheresses navrantes.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "Mon idéal, ce serait de travailler tranquille, de manger toujours du pain, d’avoir un trou un peu propre pour dormir, vous savez un lit, une table et deux chaises, pas davantage…", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "On peut bien mettre ce qu'on voudra, un roi, un empereur, rien du tout, ça ne m'empêchera pas de gagner mes cinq francs, de manger et de dormir, pas vrai ?… Non, c'est trop bête !", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "Ah ! la crevaison des pauvres, les entrailles vides qui crient la faim, le besoin des bêtes claquant des dents et s'empiffrant de choses immondes, dans ce grand Paris si doré et si flambant !", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "La religion tolérait bien des faiblesses, quand on gardait les convenances.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "On n'aime bien que les femmes qu'on n'a pas eues.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "Chaque fois que la science avance d'un pas, c'est qu'un imbécile la pousse, sans faire exprès.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "Tout n'est que rêve.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "Mais les bêtes sauvages restent des bêtes sauvages, et on aura beau inventer des mécaniques meilleures encore, il y aura quand même des bêtes sauvages dessous.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "L'idée de charité le blessait, le jetait hors de lui : la charité c'était l'aumône, l'inégalité consacrée par la bonté ; et il n'admettait que la justice, les droits de chacun reconquis, posés en immuables principes de la nouvelle organisation sociale.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "Oui, demain est aux grands capitaux, aux efforts centralisés des grandes masses. Toute l'industrie, tout le commerce, finiront par n'être qu'un immense bazar unique, où l'on s'approvisionnera de tout.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "L'argent [est] le fumier dans lequel pousse l'humanité de demain. [...] L'argent, empoisonneur et destructeur, devenait le ferment de toute végétation sociale, servait de terreau nécessaire aux grands travaux dont l'exécution rapprocherait les peuples et pacifierait la terre.", Author = "Émile Zola" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Émile_Zola", Text = "Aucun bonheur n'est possible dans l'ignorance, la certitude seule fait la vie calme.", Author = "Émile Zola" },
